/* CSS PART 2 OF 2 */

/* CONTACT AND CONVERSION */
.contact-section {
  padding-block: var(--section-space);
  background: var(--sage-light);
}

.contact-inner {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: 90px;
}

.contact-copy {
  max-width: 440px;
}

.contact-copy h2 {
  margin-bottom: 24px;
}

.contact-copy p {
  font-size: 1.02rem;
}

.contact-highlight {
  margin-top: 35px;
  padding: 22px 24px;
  border-left: 3px solid var(--sage);
  background: rgba(255, 255, 255, 0.55);
  color: var(--forest);
  font-family: var(--font-display);
  font-size: 1.3rem;
  line-height: 1.45;
}

.contact-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
  padding: 38px;
  background: var(--paper);
  box-shadow: var(--shadow);
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--forest);
  font-size: 0.78rem;
  font-weight: 700;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid var(--border);
  border-radius: 2px;
  background: var(--paper);
  color: var(--ink);
  transition: border-color 180ms ease, box-shadow 180ms ease;
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858c82;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--sage);
  outline: none;
  box-shadow: 0 0 0 3px rgba(120, 139, 104, 0.16);
}

.contact-form .button {
  justify-self: start;
}

.form-note {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--muted);
  font-size: 0.78rem;
}

/* FOOTER */
.site-footer {
  padding: 58px 0 30px;
  background: var(--forest-deep);
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding-bottom: 38px;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 15px;
}

.footer-brand .brand__logo {
  width: 48px;
  height: 48px;
}

.footer-brand .brand__text {
  color: var(--white);
}

.footer-brand .brand__subtitle {
  color: rgba(255, 255, 255, 0.65);
}

.footer-contact {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 24px;
}

.footer-contact a {
  color: rgba(255, 255, 255, 0.84);
  font-size: 0.84rem;
  transition: color 180ms ease;
}

.footer-contact a:hover {
  color: #d0dfb9;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.18);
}

.footer-bottom p {
  margin: 0;
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.76rem;
}

/* ACCESSIBLE MOBILE MENU BUTTON */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  padding: 0;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: transparent;
  color: var(--forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* RESPONSIVE: TABLET */
@media (max-width: 1000px) {
  :root {
    --section-space: 82px;
    --header-height: 76px;
  }

  .container,
  .hero__content {
    width: calc(100% - 48px);
  }

  .header-inner {
    width: calc(100% - 48px);
    gap: 20px;
  }

  .primary-nav {
    gap: 20px;
  }

  .intro,
  .difference,
  .local-sourcing {
    gap: 55px;
  }

  .contact-inner {
    gap: 45px;
  }

  .services__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .service-item {
    min-height: 180px;
  }
}

/* RESPONSIVE: MOBILE NAVIGATION */
@media (max-width: 760px) {
  :root {
    --section-space: 68px;
    --header-height: 72px;
  }

  html {
    scroll-padding-top: 80px;
  }

  .container,
  .hero__content {
    width: calc(100% - 40px);
  }

  .header-inner {
    width: calc(100% - 40px);
    min-height: var(--header-height);
  }

  .brand__logo {
    width: 44px;
    height: 44px;
  }

  .brand__text {
    font-size: 1.15rem;
  }

  .brand__subtitle {
    font-size: 0.53rem;
  }

  .menu-toggle {
    display: flex;
    flex-shrink: 0;
  }

  .primary-nav {
    display: none;
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    max-height: calc(100svh - var(--header-height));
    overflow-y: auto;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 12px 20px 22px;
    border-top: 1px solid var(--border);
    background: var(--paper);
    box-shadow: 0 15px 25px rgba(23, 46, 37, 0.12);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    display: block;
    padding: 15px 4px;
    border-bottom: 1px solid var(--border);
  }

  .primary-nav .button {
    width: 100%;
    margin: 15px 0 0;
  }

  .hero {
    min-height: 680px;
    min-height: min(760px, calc(100svh - var(--header-height)));
  }

  .hero__media {
    object-position: 60% center;
  }

  .hero::after {
    background: linear-gradient(
      90deg,
      rgba(17, 39, 29, 0.82),
      rgba(17, 39, 29, 0.55)
    );
  }

  .hero__content {
    padding-block: 90px;
  }

  .hero__title {
    max-width: 600px;
    font-size: clamp(3.25rem, 12vw, 5.2rem);
  }

  .hero__description {
    max-width: 460px;
    font-size: 1rem;
  }

  .intro,
  .difference,
  .local-sourcing,
  .contact-inner {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .intro__heading,
  .intro__body,
  .difference__content,
  .contact-copy {
    max-width: none;
  }

  .services__header {
    display: block;
    margin-bottom: 35px;
  }

  .services__description {
    max-width: 500px;
    margin-top: 20px;
  }

  .services__grid {
    grid-template-columns: 1fr 1fr;
  }

  .service-item {
    min-height: 165px;
    padding: 24px;
  }

  .service-item__number {
    margin-bottom: 18px;
  }

  .difference__visual,
  .difference__visual img {
    min-height: 320px;
    max-height: 440px;
  }

  .local-sourcing__body {
    max-width: none;
  }

  .contact-form {
    padding: 28px;
  }

  .footer-main {
    align-items: flex-start;
    flex-direction: column;
    gap: 28px;
  }
}

/* RESPONSIVE: SMALL MOBILE */
@media (max-width: 480px) {
  :root {
    --section-space: 56px;
  }

  body {
    font-size: 15px;
  }

  .container,
  .hero__content {
    width: calc(100% - 36px);
  }

  .header-inner {
    width: calc(100% - 36px);
  }

  h2 {
    font-size: clamp(2.25rem, 10vw, 3rem);
  }

  .hero {
    min-height: 650px;
  }

  .hero__content {
    padding-block: 75px;
  }

  .hero__title {
    font-size: clamp(3rem, 13vw, 4.2rem);
  }

  .hero__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero__actions .button {
    width: 100%;
  }

  .hero__note {
    font-size: 0.69rem;
  }

  .services__grid {
    grid-template-columns: 1fr;
  }

  .service-item {
    min-height: 0;
    padding: 25px;
  }

  .contact-form {
    grid-template-columns: 1fr;
    gap: 18px;
    padding: 22px 18px;
  }

  .form-field--full,
  .form-note {
    grid-column: 1;
  }

  .contact-form .button {
    width: 100%;
  }

  .footer-contact {
    align-items: flex-start;
    flex-direction: column;
    gap: 14px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 10px;
  }

  .contact-highlight {
    font-size: 1.15rem;
  }
}

/* KEYBOARD FOCUS */
a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--earth);
  outline-offset: 4px;
}

.menu-toggle:focus-visible,
.button:focus-visible {
  outline-color: var(--earth);
  outline-offset: 4px;
}

/* REDUCED MOTION */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
